static const lv_image_dsc_t subtract_img = {
    .header = {.magic=LV_IMAGE_HEADER_MAGIC,.cf=LV_COLOR_FORMAT_A8,.flags=0,.w=32,.h=32,.stride=32,.reserved_2=0},
    .data_size = sizeof(subtract_buf),
    .data = subtract_buf,
    .reserved = NULL,
};

static const lv_image_dsc_t *descriptor_for(ui_remote_icon_t type)
{
    switch(type) {
        case UI_REMOTE_ICON_POWER: return &power_img;
        case UI_REMOTE_ICON_INPUT: return &input_img;
        case UI_REMOTE_ICON_HOME: return &home_img;
        case UI_REMOTE_ICON_BACK: return &back_img;
        case UI_REMOTE_ICON_SETTINGS: return &settings_img;
        case UI_REMOTE_ICON_DISPLAY: return &display_img;
        case UI_REMOTE_ICON_ADD: return &add_img;
        case UI_REMOTE_ICON_SUBTRACT: return &subtract_img;
        default: return &power_img;
    }
}

lv_obj_t *ui_remote_icon_create(lv_obj_t *parent, ui_remote_icon_t icon, lv_color_t color)
{
    lv_obj_t *image = lv_image_create(parent);
    lv_image_set_src(image, descriptor_for(icon));
    lv_obj_set_style_image_recolor(image, color, 0);
    lv_obj_set_style_image_recolor_opa(image, LV_OPA_COVER, 0);
    lv_obj_clear_flag(image, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_clear_flag(image, LV_OBJ_FLAG_SCROLLABLE);
    return image;
}
